# -*- coding: utf-8 -*-
import sys, os
sys.stdout.reconfigure(encoding='utf-8')

csv_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "\uad50\uc721\ud504\ub85c\uadf8\ub7a8.csv")

# Read raw bytes, detect encoding
for enc in ("utf-8-sig", "utf-8", "cp949"):
    try:
        with open(csv_path, encoding=enc, newline="") as f:
            content = f.read()
        used_enc = enc
        break
    except Exception:
        continue

print(f"Encoding: {used_enc}, lines: {content.count(chr(10))}")

# Key: (col_index_for_match, match_value) -> (goal, detail, notice_extra)
PATCHES = [
    ("\uc5bc\uc74c\uacf5", "\uc6b0\ubc15 \ubaa8\ud615\uc744 \ub9cc\ub4e4\uc5b4\ubcf4\uace0 \uae30\uc0c1\ud604\uc0c1\uc5d0 \uad00\uc2ec\uc744 \uac16\ub294\ub2e4. / \uc6b0\ubc15\uc758 \ub2e8\uba74 \uad6c\uc870(\uce35)\ub97c \uc54c\uace0 \ud06c\uae30\uc5d0 \ub530\ub978 \uc704\ud5d8\uc131\uc744 \ub290\ub08c\ub2e4.", "\ub0b4\uc6a9: \ube44\u00b7\ub208\u00b7\uc6b0\ubc15\uc758 \ucc28\uc774 / \uc6b0\ubc15\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uacfc\uc815 / \uc6b0\ubc15\uc758 \ub2e8\uba74\u00b7\ud06c\uae30\u00b7\ud53c\ud574 | \ud65c\ub3d9: \uc6b0\ubc15 \ud615\uc131 \uacfc\uc815 \uc2a4\ud2f0\ub85c\ud3fc \uacf5 \uc2e4\ud5d8 / \ud074\ub808\uc774\ub85c \ub9cc\ub4e4\uc5b4 \uc6b0\ubc15 \ud06c\uae30\u00b7\ubb34\uac8c \ube44\uad50 / \uce35 \uad6c\uc870 \ub2e8\uba74 \ubaa8\ube4c \ub9cc\ub4e4\uae30"),
    ("\uc138\uc885\uacfc \uc7a5\uc601\uc2e4\uc758 \uc2dc\uac04 \uc5ec\ud589", "\uc138\uc885\ub300\uc655\uc774 \uc2dc\uac04\uc744 \uc815\ud655\ud788 \uc54c\uace0\uc790 \ud588\ub358 \uc774\uc720\ub97c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. / \uc7a5\uc601\uc2e4\uc774 \ubc1c\uba85\ud55c \uae30\uad6c\ub4e4\uc774 \uc5b4\ub5a4 \ubb38\uc81c\ub97c \ud574\uacb0\ud588\ub294\uc9c0 \uc124\uba85\ud560 \uc218 \uc788\ub2e4. / \uc2dc\uac04\uc744 \uce21\uc815\ud558\uace0 \uae30\ub85d\ud558\ub294 \uac83\uc774 \uc65c \uc911\uc694\ud55c\uc9c0 \ub9d0\ud560 \uc218 \uc788\ub2e4.", "\ub0b4\uc6a9: \uc815\ud655\ud55c \uc2dc\uac04\uacfc \uae30\ub85d\uc758 \ud544\uc694\uc131\uc744 \uc778\uc2dd\ud55c \ubc30\uacbd / \uc559\ubd80\uc77c\uad6c\u00b7\uc790\uaca9\ub8e8\u00b7\uce21\uc6b0\uae30\ub97c \ud1b5\ud574 \ubb38\uc81c\ub97c \ud574\uacb0\ud55c \uacfc\uc815 / \ud0dc\uc591\uacfc \uadf8\ub9bc\uc790\ub97c \uc774\uc6a9\ud55c \uc2dc\uac04 \uce21\uc815 \ubc29\ubc95 / \ube44\uc758 \uc591\uc744 \ub208\uae08\uc73c\ub85c \uce21\uc815\ud558\uace0 \uae30\ub85d\ud558\ub294 \uc774\uc720 \ud0d0\uad6c | \ud65c\ub3d9: \uc790\uaca9\ub8e8 \uac04\uc774 \uc2e4\ud5d8 \ubc0f \uce21\uc6b0\uae30 \ub9cc\ub4e4\uae30(1~2\ud559\ub144) / \uc790\uaca9\ub8e8 \uac04\uc774 \uc2e4\ud5d8 \ubc0f \uc790\uaca9\ub8e8 \ub9cc\ub4e4\uae30(3~4\ud559\ub144) (\uac15\uc0ac: \ucc28\ubbfc\uc815)"),
    ("\ub611\ub531\ub611\ub531 \uc2dc\uac04 \ub180\uc774", "\ud574\uc640 \uadf8\ub9bc\uc790\u00b7\ubb3c\uc758 \ubcc0\ud654\ub97c \ud1b5\ud574 \uc2dc\uac04\uc774 \ud750\ub978\ub2e4\ub294 \uac83\uc744 \ub290\ub080\ub2e4. / \uc138\uc885\ub300\uc655\uacfc \uc7a5\uc601\uc2e4\uc774 \uc2dc\uac04\uc744 \uc54c\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4 \uc62c\ub9ac \ub3c4\uad6c\uc640 \ub178\ub825\uc744 \uc774\ud574\ud55c\ub2e4.", "\ub0b4\uc6a9: '\uc2dc\uac04\uc774 \uc0ac\ub77c\uc9c0\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c?'\ub97c \uc0c1\uc0c1\ud558\uba70 \uc2dc\uac04\uc758 \ud544\uc694\uc131 \uacbd\ud5d8 / \uc138\uc885\ub300\uc655\uacfc \uc7a5\uc601\uc2e4\uc774 \uc2dc\uac04\uc744 \uc54c\uc544\ub0b4\uae30 \uc704\ud574 \uace0\ubbfc\ud55c \uc774\uc57c\uae30 / \ud574\u00b7\uadf8\ub9bc\uc790\u00b7\ubb3c\uc744 \ubcf4\uba70 \uc2dc\uac04\uc774 \ubcc0\ud558\ub294 \ubaa8\uc2b5 \uad00\ucc30 | \ud65c\ub3d9: \uc7a5\uc601\uc2e4 \ub3d9\uc0c1\uc5d0\uc11c \uae30\ub150\uc0ac\uc9c4 \ub0a8\uae30\uae30 / \uce21\uc6b0\uae30 \ub9cc\ub4e4\uae30 (\uac15\uc0ac: \ucc28\ubbfc\uc815)"),
    ("\uc528\uc557\uc758 \ubaa8\ud5d8", "\uc528\uc557\ub9c8\ub2e4 \uc0dd\uae40\uc0c8\uac00 \ub2e4\ub974\ub2e4\ub294 \uac83\uc744 \uc624\uac10\uc744 \ud1b5\ud574 \ubc1c\uacac\ud55c\ub2e4. / \uc528\uc557\uc774 \ud37c\uc9c0\ub294 \uacfc\uc815\uc744 \uc9c1\uc811 \uc2e4\ud5d8\ud558\uba70 \ud765\ubbf8\ub97c \ub290\ub08c\ub2e4.", "\ub0b4\uc6a9: \uc8fc\ubcc0\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \uc528\uc557\uc758 \uc885\ub958 \ud0d0\uc0c9 / \uc528\uc557\uc758 \uc885\ub958\uc640 \ud2b9\uc9d5 \uad00\ucc30 / \uc528\uc557\uc774 \ub2e4\uc591\ud55c \ubc29\ubc95\uc73c\ub85c \uc774\ub3d9\ud558\ub294 \uc6d0\ub9ac | \ud65c\ub3d9: \uc528\uc557 \uad00\ucc30 \ubc0f \uc528\uc557\uc758 \uc774\ub3d9 \uc2e4\ud5d8 / \uc528\uc557 \ud3ed\ud0c4 \ub9cc\ub4e4\uae30 (\uac15\uc0ac: \uc774\uacbd\uc219)"),
    ("\uc5f4\ub9e4\uc640 \uc528\uc557 \ubaa8\uc591\uc5d0 \uc228\uc740 \ube44\ubc00", "\uc5ec\ub7ec \uc885\ub958\uc758 \uc5f4\ub9e4\uc640 \uc528\uc557\uc744 \uad00\ucc30\ud558\uace0 \uc548\uc804\ud558\uac8c \uc790\uc190\uc744 \ud37c\ub728\ub9ac\ub294 \ubc29\ubc95\uc744 \ud0d0\uad6c\ud55c\ub2e4.", "\ub0b4\uc6a9: \uc5f4\ub9e4\u00b7\uc528\uc557\uc744 \uad00\ucc30\ud558\uc5ec \uae30\uc900\uc744 \uc815\ud574 \ubd84\ub958 / \uc5f4\ub9e4\u00b7\uc528\uc557 \uad00\ub828 \ubc1c\uba85\ud488 \ubaa8\ud615\uc73c\ub85c \ud2b9\uc9d5 \ud0d0\uad6c | \ud65c\ub3d9: \uc5f4\ub9e4\uc640 \uc528\uc557\uc744 \uad00\ucc30\ud558\uc5ec \uadf8\ub9bc\uc774 \uc788\ub294 \ud45c\ubcf8 \ub9cc\ub4e4\uae30 / \ub2e8\ud48d\ub098\ubb34 \uc528\uc557 \ud5ec\ub9ac\ucf65\ud130\u00b7\uc528\uc557 \ubaa8\ud615 \ub9cc\ub4e4\uae30 (\uac15\uc0ac: \ud0c1\uacbd\ubbf8)"),
    ("\uc9c0\uad6c\uacfc\ud559 - \uc9c0\uad6c\uc640 \ud0dc\uc591\uacc4", "\ud0dc\uc591\uacc4\uc758 \ub73b\uc744 \uc774\ud574\ud55c\ub2e4. / \uc9c0\uad6c\uc5d0\uc11c \uad00\uce21\ud55c \ud0dc\uc591\uacc4\uc758 \ud2b9\uc9d5\uc744 \uc54c\uc544\ubcf8\ub2e4. / \ud0dc\uc591\uacc4\ub97c \uc774\ub8e8\ub294 \uac01 \ud589\uc131\uacfc \uc704\uc131\uc758 \ud2b9\uc9d5\uc744 \uc54c\uc544\ubcf8\ub2e4.", "\ub3c4\uc7a5 \ub9c8\uc744 \ub4dc\ub9bc\ud300"),  # sentinel to distinguish from row 11
]

import csv as csv_mod
rows_out = []
with open(csv_path, encoding=used_enc, newline="") as f:
    reader = csv_mod.reader(f)
    header = next(reader)
    if "\ud559\uc2b5\ubaa9\ud45c" not in header: header.append("\ud559\uc2b5\ubaa9\ud45c")
    if "\ucc28\uc2dc\ubcc4\ub0b4\uc6a9" not in header: header.append("\ucc28\uc2dc\ubcc4\ub0b4\uc6a9")
    prog_i = header.index("\ud504\ub85c\uadf8\ub7a8\uba85")
    sub_i = header.index("\uc138\ubd80\ud504\ub85c\uadf8\ub7a8\uba85")
    month_i = header.index("\uc6d4")
    goal_i = header.index("\ud559\uc2b5\ubaa9\ud45c")
    det_i = header.index("\ucc28\uc2dc\ubcc4\ub0b4\uc6a9")
    rows_out.append(header)
    for row in reader:
        while len(row) < len(header): row.append("")
        sub = row[sub_i]
        month = row[month_i]
        for p in PATCHES:
            key_sub, goal, detail = p[0], p[1], p[2]
            if sub == key_sub and not row[goal_i]:
                # only patch rows where goal is empty and month is 5 or 6 (not row 11-13 which already have data)
                if month in ("5\uc6d4", "6\uc6d4"):
                    row[goal_i] = goal
                    row[det_i] = detail
                    print(f"Patched: {month} {sub[:15]}")
        rows_out.append(row)

with open(csv_path, "w", encoding=used_enc, newline="") as f:
    csv_mod.writer(f).writerows(rows_out)

print("Done")
